const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const greatLakes = ee.Geometry.Polygon(
    [[[-92.89, 49.33], [-74.96, 49.33], [-74.96, 41.28], [-92.89, 41.28], [-92.89, 49.33]]],
    null, false
  );
  const date = '2016-02-11';
  const endDate = '2016-02-12'; // Filter up to, but not including, the next day.

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterDate(date, endDate)
    .filterBounds(greatLakes);

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No MODIS images found for February 11, 2016 over the Great Lakes.");
    console.log("C1");
    return;
  }

  const image = collection.first();
  const scale = 500; // MODIS resolution is 500m

  // Function to extract cloud state from MOD09GA 'state_1km' band
  // Bits 0-1: Cloud State (00=Clear, 01=Cloudy, 10=Mixed, 11=Not Set/Fill)
  // We consider Cloudy (01) or Mixed (10) as 'clouds present'.
  // Mask to 1 if cloudy, 0 if clear.
  const getCloudMask = (img) => {
    const qa = img.select('state_1km');
    // Extract bits 0 and 1
    const cloudState = qa.bitwiseAnd(0b11); // Isolate bits 0 and 1
    // A pixel is 'cloudy' if cloudState is 1 (Cloudy) or 2 (Mixed)
    return cloudState.eq(1).or(cloudState.eq(2)).rename('cloudy_pixels');
  };

  const cloudMask = getCloudMask(image);

  // Get count of all valid pixels and cloudy pixels within the region
  const reducer = ee.Reducer.count().combine({
    reducer2: ee.Reducer.sum(),
    sharedInputs: true
  });

  const stats = await cloudMask.reduceRegion({
    reducer: reducer,
    geometry: greatLakes,
    scale: scale,
    maxPixels: 1e9,
    tileScale: 8
  }).getInfo();

  const totalPixels = stats['cloudy_pixels_count'];
  const cloudyPixels = stats['cloudy_pixels_sum'];

  if (totalPixels === null || cloudyPixels === null) {
    console.log("Calculation of pixel counts failed.");
    console.log("C3");
    return;
  }

  if (totalPixels === 0) {
    console.log("No valid pixels found in the region after initial image selection.");
    console.log("C2");
    return;
  }

  const cloudPercentage = (cloudyPixels / totalPixels) * 100;

  console.log(`Date: ${date}`);
  console.log(`Image count: ${collectionSize}`);
  console.log(`Total valid pixels: ${totalPixels}`);
  console.log(`Cloudy pixels: ${cloudyPixels}`);
  console.log(`Cloud coverage: ${cloudPercentage.toFixed(2)}%`);

  // 5. Validation & Final Answer
  if (cloudyPixels > 0) {
    console.log("A"); // Yes, clouds are present
  } else {
    console.log("B"); // No, clouds are not present
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
